WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pc_dc_derange'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '错位排列', 'kp-pc-dc-derange', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "错位排列"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心公式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "D1=0, D2=1, D3=2, D4=9, D5=44。死记硬背！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“N 个人拿自己的帽子，结果每个人拿的都不是自己的，有几种拿法？” 这叫全错位排列。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破题"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这种题推导极其复杂（容斥原理），但在公考中只考到 5 的规模。你只需要像背圆周率一样背下这几个数字："}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "2个元素全错位：1 种"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "3个元素全错位：2 种"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "4个元素全错位：9 种"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "5个元素全错位：44 种"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、部分错位怎么考？"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "如果题目说：“5 个人中，恰好有 2 个人拿对了，剩下 3 个拿错了”。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "步骤：先用 C(5,2) 挑出拿对的 2 个人；然后乘以上面背的 D3（3个人全错位=2）。总计：C(5,2) × 2 = 20 种。"}]}]}$$ AS jsonb), NULL, '错位排列的核心考点与实战推导。', category_node.id, CAST('["数量关系", "排列组合", "错位排列"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pc_dc_derange", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
